def q(s):
    return "'" + s.replace('\\', '\\\\').replace("'", "\\'") + "'"

HERE = os.path.dirname(__file__)
for i, lang in enumerate(LANGS, start=1):
    out = ['// Privacy notice, Your privacy, the AI assistant consent and the GST',
           '// bill checks. Generated by tool/l10n_src/gen_privacy.py.',
           '// ignore_for_file: lines_longer_than_80_chars', '',
           'const Map<String, String> privacy%s = {' % lang.capitalize()]
    for r in sorted(ROWS, key=lambda r: r[0]):
        assert len(r) == 6, r[0]
        out.append('  %s: %s,' % (q(r[0]), q(r[i])))
    out.append('};')
    with open(os.path.join(HERE, '..', '..', 'lib', 'l10n', 'strings_privacy_%s.dart' % lang), 'w', encoding='utf-8') as f:
        f.write('\n'.join(out) + '\n')
